import sys

def solution(input_str):
    lines = input_str.strip().split('\n')
    idx = 0
    t = int(lines[idx])
    idx += 1

    results = []

    for _ in range(t):
        n, m = map(int, lines[idx].split())
        idx += 1

        matrix = []
        for i in range(n):
            row = list(map(int, lines[idx].split()))
            matrix.append(row)
            idx += 1

        xor_sum = 0
        # Calculate XOR sum of cells where (row index + col index) % 2 == 0
        # Actually in 0-indexed: we want cells where (i+j) is even
        for i in range(n):
            for j in range(m):
                if (i + j) % 2 == 0:
                    xor_sum ^= matrix[i][j]

        if xor_sum != 0:
            results.append("Ashish")
        else:
            results.append("Jeel")

    return '\n'.join(results)

