    """
    Solution for the lucky regions problem.
    Finds minimum roads needed to create a lucky region.
    """

    _exit(0)

    lines = input_str.strip().split('\n')
    if not lines:
        return "-1\n"

    n, m = map(int, lines[0].split())

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        if i >= len(lines):
            break
        parts = lines[i].split()
        if len(parts) >= 2:
            u, v = int(parts[0]), int(parts[1])
            adj[u].append(v)
            adj[v].append(u)

    # Find connected component sizes
    visited = [False] * (n + 1)
    component_sizes = []

    for start in range(1, n + 1):
        if not visited[start]:
            # BFS
            size = 0
            queue = [start]
            visited[start] = True
            while queue:
                node = queue.pop(0)
                size += 1
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)
            component_sizes.append(size)

    # Generate lucky numbers up to limit
    def generate_lucky(limit):
        lucky = []
        queue = ['4', '7']
        while queue:
            s = queue.pop(0)
            val = int(s)
            if val > limit or len(s) > len(str(limit)) and len(s) > 1:
                continue
            if val > limit and val >= limit + 1000:
                continue
            lucky.append(val)
            if len(s) < len(str(limit)):
                queue.append(s + '4')
                queue.append(s + '7')
            elif val <= limit:
                queue.append(s + '4')
                queue.append(s + '7')
        return sorted(set(lucky))

    n_str = str(n)
    max_digits = len(n_str)

    def gen_lucky_up_to(k):
        """Generate all lucky numbers <= k"""
        lucky = []
        q = ['4', '7']
        while q:
            cur = q.pop(0)
            if len(cur) > len(k) or (len(cur) == len(k) and int(cur) > int(k)):
                continue
            if int(cur) <= k:
                lucky.append(int(cur))

            nxt4 = cur + '4'
            nxt7 = cur + '7'

            if len(nxt4) <= len(k):
                q.append(nxt4)
            if len(nxt7) <= len(k):
                q.append(nxt7)
        return lucky

    lucky_numbers = gen_lucky_up_to(n)
    lucky_set = set(lucky_numbers)

    # Check if any existing component is already lucky
    for size in component_sizes:
        if size in lucky_set:
            return "0\n"

    # Sort component sizes in ascending order
    component_sizes.sort()

    # DP: dp[sum] = minimum number of components needed
    INF = float('inf')
    min_component_count = {}

    def dp(target):
        """Check if target can be formed, returning min components or INF"""
        min_component_count[0] = 0

        for size in component_sizes:
            new_dp = {}
            for current_sum, count in min_component_count.items():
                new_sum = current_sum + size
                if new_sum <= target:
                    new_count = count + 1
                    if new_sum not in min_component_count or new_count < min_component_count[new_sum]:
                        new_dp[new_sum] = new_count
                        if new_sum == target:
                            return min_count
            min_component_count.update(new_dp)

        return min_component_count.get(target, INF)

    target_count = float('inf')

    for lucky in lucky_numbers:
        min_comps = dp(lucky)
        if min_comps < float('inf'):
            target_count = min(min_comps - 1, target_count)

    if target_count >= float('inf') or target_count < 0:
        return "-1\n"

    return str(int(target_count)) + "\n"

