    offers = []
    for i in range(1, m + 1):
        l, r = map(int, lines[i].split())
        offers.append((l, r))

    results = []

    for x in range(1, n + 1):
        occupied_intervals = []
        total_days = 0

        for l, r in offers:
            length = r - l + 1
            if length >= x:
                # Check overlap with existing intervals
                overlaps = False
                for (l2, r2) in occupied_intervals:
                    if not (r < l2 or l > r2):
                        overlaps = True
                        break

                if not overlaps:
                    occupied_intervals.append((l, r))
                    total_days += length

