    # Count divisors of a number
    def count_divisors(x):
        count = 0
        d = 1
        while d * d <= x:
            if x % d == 0:
                count += 1
                if d * d != x:
                    count += 1
            d += 1
        return count

    # Precompute number of bridges between any two islands
    # For islands i and j, bridges = 2^(number of divisors of gcd(i,j))
    bridges = [[0] * n for _ in range(n)]
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if i != j:
                g = math.gcd(i, j)
                k = count_divisors(g)
                bridges[i-1][j-1] = 1 << k

    def mat_mul(A, B):
        C = [[0] * n for _ in range(n)]
        for i in range(n):
            for k in range(n):
                if A[i][k] == 0:
                    continue
                for j in range(n):
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
        return C

    def mat_pow(A, p):
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            result[i][i] = 1
        base = A
        while p > 0:
            if p & 1:
                result = mat_mul(result, base)
            base = mat_mul(base, base)
            p >>= 1
        return result

    initial = a  # Ways from home to each island

    # If t = 0, he just arrives (no days spent on islands)
    if t == 0:
        ans = [val % MOD for val in initial]
    else:
