        ans = [0] * n
        for j in range(n):
            for i in range(n):
                ans[i] = (ans[i] + initial[j] * adj_t[j][i]) % MOD

    # XOR sum of all answers
    result = 0
    for x in ans:
        result ^= x

    return f"{result}\n"

