    num_factors = get_prime_factors(seq[num-1]) if seq[num-1] > 1 else set()
    for i in range(num):
        factors = get_prime_factors(seq[i]) if seq[i] > 1 else set()
        if factors and num_factors and not factors.isdisjoint(num_factors):
