        if k < v_len and virus[k] == char:
            return k + 1

        # Find longest prefix of virus that could be formed after seeing this char
        # Using KMP-like fallback logic
        for next_k in range(min(k, v_len - 1), -1, -1):
            if next_k < v_len and len(virus[:min(next_k+1, v_len)] - 1) > 0:
                test_str = virus[:next_k+1][-1:] + virus[:next_k]
                if test_str.endswith(char):
                    return next_k + 1 if next_k < len(virus) else next_k
        return 0

    # Precompute transition more efficiently
    def next_v(k, c):
        if k >= v_len:
            return v_len
        if k < v_len and c == virus[k]:
            return k + 1
        # Find longest prefix suffix
        for nxt in range(min(k, v_len - 1), -1, -1):
            pattern = virus[:nxt] + c
            if pattern.endswith(virus[:nxt+1]):
                return nxt + 1
        return 0

    # Iterative DP
    # dp[i][j][k] = (max_length, parent_direction)
    # parent_direction: 'M' = match, 'S1' = skip s1, 'S2' = skip s2

    dp = {}
    state = (0, 0, 0)
    dp[state] = (0, None)

    for i in range(n + 1):
        for j in range(m + 1):
            for k in range(v_len + 1):
                if (i, j, k) not in dp:
                    continue
                cur_len, p = dp[(i, j, k)]

                # Skip s1
                if i < n:
                    new_state = (i + 1, j, k)
                    if new_state not in dp or cur_len > dp[new_state][0]:
                        dp[new_state] = (cur_len, 'S1')

                # Skip s2
                if j < m:
                    new_state = (i, j + 1, k)
                    if new_state not in dp or cur_len > dp[new_state][0]:
                        dp[new_state] = (cur_len, 'S2')

                # Match if possible
                if i < n and j < m and s1[i] == s2[j]:
                    c = s1[i]
                    nk = next_v(k, c)
                    if nk < v_len:
                        new_state = (i + 1, j + 1, nk)
                        new_len = cur_len + 1
                        if new_state not in dp or new_len > dp[new_state][0]:
                            dp[new_state] = (new_len, 'M')

    # Find max
    max_len = 0
    for s in dp:
        if dp[s][0] > max_len:
            max_len = dp[s][0]

    if max_len == 0:
        return '0'

    # Reconstruct
    result = []
    i, j, k = 0, 0, 0
    while i <= n and j <= m and dp.get((i, j, k), (0, None))[0] >= max_len:
        _, action = dp.get((i, j, k), (0, None))
        if action == 'M':
            result.append(s1[i])
            i += 1
            j += 1
        elif action == 'S1':
            i += 1
        elif action == 'S2':
            j += 1
        else:
            break

    result.reverse()
    return ''.join(result)

