def solution(input_string):
    from collections import defaultdict

    lines = input_string.strip().split('\n')
    n, m = map(int, lines[0].split())

    edges = []
    for i in range(1, m + 1):
        parts = lines[i].split()
        a, b, e = map(int, parts)
        edges.append((a, b, e))

    if m == n - 1:
        return ""

    # Kruskal's algorithm to find MST
    sorted_edges = sorted(edges, key=lambda x: x[2])

    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return False
        if rank[px] < rank[py]:
            px, py = py, px
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1
        return True

    mst_adj = defaultdict(list)

    for a, b, e in sorted_edges:
        if union(a, b):
            mst_adj[a].append((b, e))
            mst_adj[b].append((a, e))

    # Binary lifting with max edge weight tracking
    LOG = 20
    up = [[0] * LOG for _ in range(n + 1)]
    up_max = [[0] * LOG for _ in range(n + 1)]
    depth = [0] * (n + 1)

    def dfs(u, p, w, d):
        depth[u] = d
        up[u][0] = p
        up_max[u][0] = w

        for i in range(1, LOG):
            up[u][i] = up[up[u][i - 1]][i - 1]
            up_max[u][i] = max(up_max[u][i - 1], up_max[up[u][i - 1]][i - 1])

        for v, weight in mst_adj[u]:
            if v != p:
                dfs(v, u, max(w, weight), d + 1)

    dfs(1, 1, -1, 0)

    def query(u, v):
        if depth[u] < depth[v]:
            u, v = v, u

        ans = 0

        for i in range(LOG - 1, -1, -1):
            if depth[u] - (1 << i) >= depth[v]:
                ans = max(ans, up_max[u][i])
                u = up[u][i]

        if u == v:
            return ans

        for i in range(LOG - 1, -1, -1):
            if up[u][i] != up[v][i]:
                ans = max(ans, up_max[u][i], up_max[v][i])
                u = up[u][i]
                v = up[v][i]

        ans = max(ans, up_max[u][0], up_max[v][0])
        return ans

    result = []
    for a, b, e in edges:
        if find(a) == find(b):
            result.append(str(query(a, b)))

    return '\n'.join(result)

