MOD = 1000000007

def is_good(arr):
    """Check if array is 'good': all adjacent differences = 1, including wrap-around."""
    r = len(arr)
    if r <= 1:
        return False
    for i in range(r - 1):
        if abs(arr[i] - arr[i + 1]) != 1:
            return False
    return abs(arr[-1] - arr[0]) == 1

def count_distinct_good_rearrangements(arr):
    """Count how many distinct permutations of arr form good arrays."""
    seen = set()
    for perm in permutations(arr):
        if is_good(list(perm)):
            seen.add(perm)
    return len(seen)

