            results.append("-1")
            continue

        # If K = 0, any permutation works; lexicographically smallest is [1, 2, ..., N]
        if K == 0:
            results.append(" ".join(map(str, range(1, N + 1))))
            continue

        # Greedy backtracking: try values 1 to N for each position
        used = [False] * (N + 1)
        perm = []

        def backtrack(pos):
            if pos > N:
                return True

            # Try values in increasing order (for lexicographically smallest)
            for v in range(1, N + 1):
                if not used[v]:
                    # Check constraint for this value and position
                    if abs(v - pos) >= K:
                        used[v] = True
                        perm.append(v)
                        if backtrack(pos + 1):
                            return True
                        perm.pop()
                        used[v] = False

            return False

        if backtrack(1):
            results.append(" ".join(map(str, perm)))
        else:
            results.append("-1")

    return "\n".join(results)

