def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines or not lines[0].strip():
        return ''

    n = int(lines[0])
    sheep = []
    for i in range(n):
        parts = lines[i+1].split()
        l, r = int(parts[0]), int(parts[1])
        sheep.append((i+1, l, r))

    if n == 0:
        return ''

    # Build adjacency list for overlapping sheep
    adj = [[] for _ in range(n)]
    for i in range(n):
        for j in range(i+1, n):
            # Check if ranges overlap
            if sheep[i][1] <= sheep[j][2] and sheep[j][1] <= sheep[i][2]:
                adj[i].append(j)
                adj[j].append(i)

    # Try to build a long path using DFS with backtracking
    # Start from different vertices to find better paths

    best_path = []

    def dfs(start_idx, depth, path, visited):
        nonlocal best_path
        if depth > len(best_path):
            best_path = path[:]

        for neigh in adj[start_idx]:
            if neigh not in visited:
                new_visited = visited | {neigh}
                new_path = path + [neigh]
                dfs(neigh, depth + 1, new_path, new_visited)

    # Try starting from each vertex
    for start in range(n):
        visited = {start}
        path = [start]
        dfs(start, 1, path, visited)

    # Convert path to sheep indices (1-based)
    path_indices = [str(sheep[i][0]) for i in best_path]
    return ' '.join(path_indices) + '\n'

def solution(input_str):
    lines = input_str.split('\n')
    if len(lines) < 2:
        return '-1\n'

    try:
        n, h, w = map(int, lines[0].split())
    except:
        return '-1\n'

    if len(lines) < 2 or not lines[1]:
        return '-1\n'

    pattern = lines[1]

    MOD = 10**9 + 7

    # Calculate net displacement per pattern cycle
    vert_total = 0
    horiz_total = 0
    for c in pattern:
        if c == 'U':
            vert_total -= 1
        elif c == 'D':
            vert_total += 1
        elif c == 'L':
            horiz_total -= 1
        elif c == 'R':
            horiz_total += 1

    # Check if robot can cycle forever (both displacements zero and room to move)
    if vert_total == 0 and horiz_total == 0:
        if h > 1 or w > 1:
            return '-1\n'

    # Build prefix sums for all 4 directions
    U = [0] * (n + 1)
    D = [0] * (n + 1)
    L = [0] * (n + 1)
    R = [0] * (n + 1)

    curr_U, curr_D, curr_L, curr_R = 0, 0, 0, 0
    for i in range(n):
        c = pattern[i]
        if c == 'U':
            curr_U -= 1
        elif c == 'D':
            curr_D += 1
        elif c == 'L':
            curr_L -= 1
        elif c == 'R':
            curr_R += 1
        U[i + 1] = curr_U
        D[i + 1] = curr_D
        L[i + 1] = curr_L
        R[i + 1] = curr_R

    def count_moves(nr, nc, n):
        """
        For a single cell at (nr, nc) in 1-indexed grid:
        Count moves until hitting a wall
        """
        if nr == 0 or nr > h or nc == 0 or nc > w:
            return 0

        hits_vertical = False
        hit_vert_early = float('inf')

        for k in range(n):
            next_row = nr + U[k]
            if next_row <= 0 or next_row > h:
                hits_vertical = True
                hit_vert_early = k + 1
                break

        hits_horizontal = False
        hit_horiz_early = float('inf')

        for k in range(n):
            next_col = nc + R[k]
            if next_col <= 0 or next_col > w:
                hits_horizontal = True
                hit_horiz_early = k + 1
                break

        if hits_vertical and hits_horizontal:
            return min(hit_vert_early, hit_horiz_early)
        elif hits_vertical:
            return hit_vert_early
        elif hits_horizontal:
            return hit_horiz_early
        else:
            # No wall hit in one cycle - check if cycling causes wall
            # With zero net displacement, we could loop forever
            return n

    # For efficiency, use optimized approach for vertical/horizontal separately
    # and combine results
    total_moves = 0

    # Vertical contribution: for each row, how many cells hit vertical walls
    # Horizontal contribution: for each column, how many cells hit horizontal walls
    # But this double counts, so we need to be careful

    # Actually, each cell is independent - a cell at (r, c) will hit vertical wall in some pattern
    # and horizontal wall in same pattern. The answer is the minimum time to hit ANY wall

    # Use O((h+w)*n) approach: group by row/col

    for r in range(1, h + 1):
        for c in range(1, w + 1):
            t = count_moves(r, c, n)
            total_moves = (total_moves + t) % MOD

    return str(total_moves) + '\n'
